/// What the routes of component `kernel` (Kernel) need from the deployment beyond the implementation of its contracts.
pub trait KernelHooks: Send + Sync + 'static {}

/// Component `kernel` needs no hooks.
impl KernelHooks for () {}

/// Answers one call of contract `decide-intent`.
async fn serve_decide_intent<S: crate::contracts::Kernel + Sync, H: KernelHooks>(
    service: &S,
    _hooks: &H,
    _caller: strata_runtime::Caller,
    request: crate::contracts::DecideIntentRequest,
) -> Result<
    crate::contracts::DecideIntentResponse,
    strata_runtime::Failure<crate::contracts::DecideIntentError>,
> {
    service
        .decide_intent(request)
        .await
        .map_err(|error| strata_runtime::Failure::Contract { error })
}

