/// What the routes of component `runtime` (Runtime) need from the deployment beyond the implementation of its contracts.
pub trait RuntimeHooks: Send + Sync + 'static {}

/// Component `runtime` needs no hooks.
impl RuntimeHooks for () {}

/// Answers one call of contract `health-check`.
async fn serve_health_check<S: crate::contracts::Runtime + Sync, H: RuntimeHooks>(
    service: &S,
    _hooks: &H,
    _caller: strata_runtime::Caller,
    request: crate::contracts::HealthCheckRequest,
) -> Result<
    crate::contracts::HealthCheckResponse,
    strata_runtime::Failure<crate::contracts::HealthCheckError>,
> {
    service
        .health_check(request)
        .await
        .map_err(|error| strata_runtime::Failure::Contract { error })
}

