/// What the routes of component `automation-worker` (Automation worker) need from the deployment beyond the implementation of its contracts.
pub trait AutomationWorkerHooks: Send + Sync + 'static {}

/// Component `automation-worker` needs no hooks.
impl AutomationWorkerHooks for () {}

/// Answers one call of contract `schedule-job`.
async fn serve_schedule_job<
    S: crate::contracts::AutomationWorker + Sync,
    H: AutomationWorkerHooks,
>(
    service: &S,
    _hooks: &H,
    _caller: strata_runtime::Caller,
    request: crate::contracts::ScheduleJobRequest,
) -> Result<
    crate::contracts::ScheduleJobResponse,
    strata_runtime::Failure<crate::contracts::ScheduleJobError>,
> {
    service
        .schedule_job(request)
        .await
        .map_err(|error| strata_runtime::Failure::Contract { error })
}

