/// Adds a route for every contract component `subject-rights-service` implements to `routes`, each answered by `service` after the checks the specification states for it.
pub fn subject_rights_service_routes<A, S, H>(
    routes: strata_runtime::Routes<A>,
    service: std::sync::Arc<S>,
    hooks: std::sync::Arc<H>,
) -> strata_runtime::Routes<A>
where
    A: strata_runtime::Authorizer,
    S: crate::contracts::SubjectRightsService + Send + Sync + 'static,
    H: SubjectRightsServiceHooks,
{
    routes
        .serve_checked::<
            IssueAccessGrant,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::IssueAccessGrantRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_issue_access_grant(&*service, &*hooks, caller, request).await
                }
            }
        })
        .serve_checked::<
            WithdrawAccessGrant,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::WithdrawAccessGrantRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_withdraw_access_grant(&*service, &*hooks, caller, request)
                        .await
                }
            }
        })
        .serve_checked::<
            ExportSubjectData,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::ExportSubjectDataRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_export_subject_data(&*service, &*hooks, caller, request).await
                }
            }
        })
        .serve_checked::<
            RectifySubjectField,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::RectifySubjectFieldRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_rectify_subject_field(&*service, &*hooks, caller, request)
                        .await
                }
            }
        })
        .serve_checked::<
            RestrictSubject,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::RestrictSubjectRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_restrict_subject(&*service, &*hooks, caller, request).await
                }
            }
        })
        .serve_checked::<
            EraseSubject,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::EraseSubjectRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_erase_subject(&*service, &*hooks, caller, request).await
                }
            }
        })
        .serve_checked::<
            GetProcessingRecord,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::GetProcessingRecordRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_get_processing_record(&*service, &*hooks, caller, request)
                        .await
                }
            }
        })
        .serve_checked::<
            PlaceLegalHold,
            _,
            _,
        >({
            let (service, hooks) = (service.clone(), hooks.clone());
            move |
                caller: strata_runtime::Caller,
                request: crate::contracts::PlaceLegalHoldRequest|
            {
                let (service, hooks) = (service.clone(), hooks.clone());
                async move {
                    serve_place_legal_hold(&*service, &*hooks, caller, request).await
                }
            }
        })
}

