/// A refusal of the runtime rather than of the contract.
fn refusal<E>(
    code: strata_runtime::FailureCode,
    message: impl Into<String>,
) -> strata_runtime::Failure<E> {
    strata_runtime::Failure::Runtime {
        code,
        message: message.into(),
    }
}
